# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ETİL ALKOL VE LAKTİK ASİT FERMANTASYONU KARŞILAŞTIRMASI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ETİL ALKOL FERMANTASYONU</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Glikoz (6C) → 2 Pirüvat (3C) [Glikoliz: Net 2 ATP]</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• 2 Pirüvat (3C) → 2 Asetaldehit (2C) + 2 CO2 çıkışı</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• 2 Asetaldehit + 2 NADH → 2 Etil Alkol (2C) + 2 NAD+</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• Son elektron alıcısı: Asetaldehit (organik ara ürün)</text>\n  <text x="35" y="184" font-size="11.2" fill="#1e3a8a">• Canlılar: Bira mayası mantarı, bazı bakteriler, bitki tohumu</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">LAKTİK ASİT FERMANTASYONU</text>\n  <text x="370" y="88" font-size="11.2" fill="#7f1d1d">• Glikoz (6C) → 2 Pirüvat (3C) [Glikoliz: Net 2 ATP]</text>\n  <text x="370" y="112" font-size="11.2" fill="#7f1d1d">• 2 Pirüvat (3C) + 2 NADH → 2 Laktik Asit (3C) + 2 NAD+</text>\n  <text x="370" y="136" font-size="11.2" fill="#7f1d1d">• Karbondioksit (CO2) çıkışı kesinlikle GÖRÜLMEZ!</text>\n  <text x="370" y="160" font-size="11.2" fill="#7f1d1d">• Son elektron alıcısı: Doğrudan Pirüvat (3C)</text>\n  <text x="370" y="184" font-size="11.2" fill="#7f1d1d">• Canlılar: Yoğurt bakterileri, memeli olgun alyuvarı, çizgili kas</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Son ürün evresinde ATP üretilmez; amaç NADH moleküllerini yükseltgeyip NAD+ koenzimini glikolize geri kazandırmaktır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">FERMANTASYON DENEY DÜZENEĞİ VE DEĞİŞKEN ANALİZİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">MAYA MANTARI DENEY DÜZENEĞİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#14532d">• Cam balon içeriği: Ilık su (30-35 °C) + Glikoz + Maya</text>\n  <text x="35" y="112" font-size="11.2" fill="#14532d">• Gözlem 1: Balonun şişmesi ve kireç suyunun bulanması (CO2)</text>\n  <text x="35" y="136" font-size="11.2" fill="#14532d">• Gözlem 2: Termometrede sıcaklık artışı (ısı çıkışı)</text>\n  <text x="35" y="160" font-size="11.2" fill="#14532d">• Gözlem 3: Glikoz miktarının ve pH değerinin azalması</text>\n  <text x="35" y="184" font-size="11.2" fill="#14532d">• Biriken etil alkol %18\'i aşarsa maya hücreleri zehirlenir</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">ENDÜSTRİYEL ÖNEM VE CORI DÖNGÜSÜ</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Ekmek mayalanması: CO2 gazı hamuru kabartır</text>\n  <text x="370" y="112" font-size="11.2" fill="#581c87">• Yoğurt, kefir, peynir, turşu: Laktik asit fermantasyonu</text>\n  <text x="370" y="136" font-size="11.2" fill="#581c87">• Çizgili kaslarda acil ATP: O2 yetersizliğinde laktik asit</text>\n  <text x="370" y="160" font-size="11.2" fill="#581c87">• Dinlenme anında laktik asit → Karaciğerde pirüvat/glikoza</text>\n  <text x="370" y="184" font-size="11.2" fill="#581c87">• Memeli olgun alyuvarı: Mitokondrisi yoktur, yalnız laktik asit</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Fermantasyonun tüm basamakları hem prokaryot hem de ökaryot hücrelerde sitoplazmada gerçekleşir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DOĞADA ENERJİ AKIŞI: FOTOSENTEZ VE HÜCRESEL SOLUNUM İLİŞKİSİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">KLOROPLAST (FOTOSENTEZ - ANABOLİK)</text>\n  <text x="35" y="88" font-size="11.2" fill="#064e3b">• Girenler: 6 CO2 + 6 H2O + Işık Enerjisi</text>\n  <text x="35" y="112" font-size="11.2" fill="#064e3b">• Çıkanlar: C6H12O6 (Organik besin) + 6 O2</text>\n  <text x="35" y="136" font-size="11.2" fill="#064e3b">• Enerji dönüşümü: Işık enerjisi → Kimyasal bağ enerjisi</text>\n  <text x="35" y="160" font-size="11.2" fill="#064e3b">• Hidrojen ve elektron taşıyıcı koenzim: NADP+ (NADPH)</text>\n  <text x="35" y="184" font-size="11.2" fill="#064e3b">• Fotofosforilasyonla üretilen ATP yalnız fotosentezde harcanır</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">MİTOKONDRİ (OKSİJENLİ SOLUNUM - KATABOLİK)</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• Girenler: C6H12O6 (Organik besin) + 6 O2</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• Çıkanlar: 6 CO2 + 6 H2O + ATP + Isı</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• Enerji dönüşümü: Kimyasal bağ enerjisi → ATP ve Isı</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• Hidrojen ve elektron taşıyıcı koenzimler: NAD+ ve FAD</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Substrat düzeyinde ve oksidatif fosforilasyon görülür</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Madde (C, H, O) fotosentez ve solunum arasında döngüsel olarak aktarılırken, enerji akışı tek yönlüdür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
